const req=msg.monthReq||{};
const id=String(req.rid||"");
if(!id)return null;

let pending=context.get("monthlyPending")||{};
const now=Date.now();

for(const k of Object.keys(pending)){
  if(now-Number(pending[k].created||0)>60000) delete pending[k];
}

if(!pending[id]){
  pending[id]={
    created:now,
    req,
    h:false,
    c:false,
    cw:false,
    history:[],
    current:[],
    currentCodeWise:[],
    currentTimeline:[],
    error:""
  };
}

const e=pending[id];

if(msg.topic==="history"){
  e.h=true;
  e.history=Array.isArray(msg.payload)?msg.payload:[];
}else if(msg.topic==="current"){
  e.c=true;
  e.current=Array.isArray(msg.payload)?msg.payload:[];
}else if(msg.topic==="current_codewise"){
  e.cw=true;
  e.currentCodeWise=Array.isArray(msg.payload)?msg.payload:[];
  e.currentTimeline=Array.isArray(msg.currentTimeline)?msg.currentTimeline:[];
  e.currentDiagnostics=msg.currentDiagnostics||{};
}else if(msg.topic==="history_error"){
  e.h=true;
  e.error=String(msg.error?.message||"MongoDB monthly query failed");
}else if(msg.topic==="current_error"){
  e.c=true;
  e.error=String(msg.error?.message||"Current shift runtime data failed");
}else if(msg.topic==="codewise_error"){
  e.cw=true;
  e.error="Current shift code-wise Influx query failed: "+String(msg.error?.message||msg.error||"unknown error");
}else{
  return null;
}

pending[id]=e;
context.set("monthlyPending",pending);

if(!e.h||!e.c||!e.cw) return null;

delete pending[id];
context.set("monthlyPending",pending);

if(e.error){
  msg.statusCode=500;
  msg.payload={success:false,error:e.error};
  return msg;
}

function round(v,n=2){
  const f=10**n;
  return Math.round((Number(v||0)+Number.EPSILON)*f)/f;
}

function size(v){
  const s=String(v||"").trim().toLowerCase().replace(/\s+/g,"").replace(/×/g,"x");
  return s||"Unknown";
}

function code(v){
  const s=String(v||"").trim();
  return s||"Unknown";
}

function area(s,c){
  const d=String(s||"")
    .toLowerCase()
    .replace(/\s+/g,"")
    .split("x")
    .map(Number);

  return d.length===2 &&
         d.every(x=>Number.isFinite(x)&&x>0)
    ? d[0]*d[1]/10000*Number(c||0)
    : 0;
}

function isoOrNull(value){
  if(value===undefined||value===null||value==="") return null;
  const ms=new Date(value).getTime();
  return Number.isFinite(ms)?new Date(ms).toISOString():null;
}

function shiftRank(shift){
  return ({"06-14":0,"14-22":1,"22-06":2})[shift]??9;
}

function numericSequence(value,fallback){
  const n=Number(value);
  return Number.isFinite(n)&&n>0?n:fallback;
}

const r=e.req;

// ============================================================
// COMPLETED SHIFTS FROM MONGODB
// ============================================================
const dedupe=new Map();

for(const doc of e.history){
  const x=doc?.lineStats||{};
  const date=String(x.shiftDate||"");
  const shift=String(x.shift||"");

  if(!date||!shift) continue;

  // Current active shift must come from runtime/Influx, never Mongo.
  if(r.include && date===r.currentDate && shift===r.currentShift) continue;

  const key=`${x.device||r.device}|${date}|${shift}`;
  const t=new Date(x.updatedAt||0).getTime()||0;
  const old=dedupe.get(key);

  if(!old||t>=old.t){
    const s=size(x.tileSize);
    const prod=Number(x.production||0);
    const count=Number(x.tileCount||0);

    const historicalCodeWise=
      Array.isArray(x.codeWiseProduction)
        ? x.codeWiseProduction.map((item,index)=>({
            sequence:numericSequence(item.sequence,index+1),
            designCode:code(item.designCode),
            tileSize:size(item.tileSize),
            firstProducedAt:isoOrNull(item.firstProducedAt),
            lastProducedAt:isoOrNull(item.lastProducedAt),
            tileCount:Math.max(0,Number(item.tileCount||0)),
            production:Math.max(0,Number(item.production||0)),
            live:false
          })).sort((a,b)=>a.sequence-b.sequence)
        : [];

    // Prefer the true A -> B -> A timeline saved by the new shift-end flow.
    // Fall back to the unique-code list for older MongoDB documents.
    const sourceTimeline=
      Array.isArray(x.codeWiseProductionTimeline) && x.codeWiseProductionTimeline.length
        ? x.codeWiseProductionTimeline
        : historicalCodeWise.map(item=>({
            sequence:item.sequence,
            designCode:item.designCode,
            tileSize:item.tileSize,
            startTime:item.firstProducedAt,
            endTime:item.lastProducedAt,
            tileCount:item.tileCount,
            production:item.production
          }));

    const historicalTimeline=sourceTimeline
      .map((item,index)=>({
        sequence:numericSequence(item.sequence,index+1),
        designCode:code(item.designCode),
        tileSize:size(item.tileSize),
        startTime:isoOrNull(item.startTime||item.firstProducedAt),
        endTime:isoOrNull(item.endTime||item.lastProducedAt),
        tileCount:Math.max(0,Number(item.tileCount||0)),
        production:Math.max(0,Number(item.production||0)),
        live:false
      }))
      .sort((a,b)=>a.sequence-b.sequence);

    dedupe.set(key,{
      t,
      shiftDate:date,
      shift,
      production:prod,
      tileCount:count,
      live:false,
      sizes:[
        {
          size:s,
          production:prod,
          tileCount:count,
          live:false
        }
      ],
      codeWiseProduction:historicalCodeWise,
      codeWiseProductionTimeline:historicalTimeline
    });
  }
}

const shifts=[...dedupe.values()].map(({t,...x})=>x);

// ============================================================
// CURRENT ACTIVE SHIFT TOTAL FROM RUNTIME
// ============================================================
if(r.include){
  const map=new Map();

  // Current production uses event-tagged code/size increments from Influx.
  // Runtime count is retained only for reconciliation, never size allocation.
  for(const row of e.currentCodeWise){
    const s=size(row.tileSize);
    const count=Math.max(0,Number(row._value||0));
    const x=map.get(s)||{size:s,tileCount:0,production:0,live:true};
    x.tileCount+=count;
    x.production+=area(s,count);
    map.set(s,x);
  }

  if(!map.size){
    const s=size(r.fallbackTileSize);
    map.set(s,{
      size:s,
      tileCount:0,
      production:0,
      live:true
    });
  }

  const sizes=[...map.values()].map(x=>({
    ...x,
    production:round(x.production)
  }));

  // ==========================================================
  // CURRENT ACTIVE SHIFT CODE-WISE FROM INFLUX
  // ==========================================================
  const cwMap=new Map();

  for(const row of e.currentCodeWise){
    const designCode=code(row.designCode);
    const tileSize=size(row.tileSize);
    const tileCount=Math.max(0,Number(row._value||0));
    const key=`${designCode}|||${tileSize}`;

    const x=cwMap.get(key)||{
      sequence:numericSequence(row.sequence,cwMap.size+1),
      designCode,
      tileSize,
      firstProducedAt:isoOrNull(row.firstProducedAt),
      lastProducedAt:isoOrNull(row.lastProducedAt),
      tileCount:0,
      production:0,
      live:true
    };

    x.tileCount+=tileCount;
    x.production+=area(tileSize,tileCount);

    const first=isoOrNull(row.firstProducedAt);
    const last=isoOrNull(row.lastProducedAt);

    if(first&&(!x.firstProducedAt||first<x.firstProducedAt)) x.firstProducedAt=first;
    if(last&&(!x.lastProducedAt||last>x.lastProducedAt)) x.lastProducedAt=last;

    cwMap.set(key,x);
  }

  const codeWiseProduction=[...cwMap.values()]
    .map(x=>({
      ...x,
      tileCount:Math.round(x.tileCount),
      production:round(x.production)
    }))
    .sort((a,b)=>a.sequence-b.sequence);

  const codeWiseProductionTimeline=e.currentTimeline
    .map((item,index)=>{
      const tileSize=size(item.tileSize);
      const tileCount=Math.max(0,Number(item._value??item.tileCount??0));

      return {
        sequence:numericSequence(item.sequence,index+1),
        designCode:code(item.designCode),
        tileSize,
        startTime:isoOrNull(item.startTime),
        endTime:isoOrNull(item.endTime),
        tileCount:Math.round(tileCount),
        production:round(area(tileSize,tileCount)),
        live:true
      };
    })
    .sort((a,b)=>a.sequence-b.sequence);

  const runtimeTileCount=e.current.reduce((sum,x)=>sum+Math.max(0,Number(x._value||0)),0);
  const recordedTileCount=sizes.reduce((sum,x)=>sum+x.tileCount,0);
  const unclassifiedTileCount=sizes.reduce((sum,x)=>sum+(area(x.size,1)>0?0:x.tileCount),0);
  const countDifference=runtimeTileCount-recordedTileCount;
  const productionComplete=countDifference===0 && unclassifiedTileCount===0 &&
    Number(e.currentDiagnostics?.ignoredRollbacks||0)===0;

  shifts.push({
    shiftDate:r.currentDate,
    shift:r.currentShift,
    production:round(sizes.reduce((a,x)=>a+x.production,0)),
    tileCount:sizes.reduce((a,x)=>a+x.tileCount,0),
    live:true,
    runtimeTileCount,recordedTileCount,countDifference,unclassifiedTileCount,productionComplete,
    sizes,
    codeWiseProduction,
    codeWiseProductionTimeline
  });
}

// One authoritative chronological shift order for all later calculations.
shifts.sort((a,b)=>
  a.shiftDate.localeCompare(b.shiftDate) ||
  shiftRank(a.shift)-shiftRank(b.shift)
);

// ============================================================
// DAILY + SIZE TOTALS
// ============================================================
const dayMap=new Map();
const sizeMap=new Map();

for(const s of shifts){
  if(!dayMap.has(s.shiftDate)){
    dayMap.set(s.shiftDate,{
      date:s.shiftDate,
      totalProduction:0,
      shifts:[]
    });
  }

  const d=dayMap.get(s.shiftDate);
  d.totalProduction+=Number(s.production||0);
  d.shifts.push(s);

  for(const z of s.sizes||[]){
    const key=size(z.size);
    const x=sizeMap.get(key)||{
      size:key,
      production:0,
      currentShiftProduction:0
    };

    x.production+=Number(z.production||0);

    if(s.live){
      x.currentShiftProduction+=Number(z.production||0);
    }

    sizeMap.set(key,x);
  }
}

// ============================================================
// MONTHLY UNIQUE CODE TOTALS IN FIRST-PRODUCED ORDER
// ============================================================
const codeMap=new Map();

for(const s of shifts){
  const items=[...(s.codeWiseProduction||[])]
    .sort((a,b)=>numericSequence(a.sequence,999999)-numericSequence(b.sequence,999999));

  for(const item of items){
    const designCode=code(item.designCode);
    const tileSize=size(item.tileSize);
    const key=`${designCode}|||${tileSize}`;

    const x=codeMap.get(key)||{
      designCode,
      tileSize,
      firstShiftDate:s.shiftDate,
      firstShift:s.shift,
      firstShiftSequence:numericSequence(item.sequence,1),
      firstProducedAt:isoOrNull(item.firstProducedAt),
      lastProducedAt:isoOrNull(item.lastProducedAt),
      tileCount:0,
      production:0,
      currentShiftTileCount:0,
      currentShiftProduction:0
    };

    const first=isoOrNull(item.firstProducedAt);
    const last=isoOrNull(item.lastProducedAt);

    if(first&&(!x.firstProducedAt||first<x.firstProducedAt)) x.firstProducedAt=first;
    if(last&&(!x.lastProducedAt||last>x.lastProducedAt)) x.lastProducedAt=last;

    if(s.live){
      x.currentShiftTileCount+=Number(item.tileCount||0);
      x.currentShiftProduction+=Number(item.production||0);
    }else{
      x.tileCount+=Number(item.tileCount||0);
      x.production+=Number(item.production||0);
    }

    codeMap.set(key,x);
  }
}

// ============================================================
// MONTH-WIDE CHRONOLOGICAL RUN TIMELINE
// ============================================================
const monthlyTimeline=[];

for(const s of shifts){
  const source=
    Array.isArray(s.codeWiseProductionTimeline) && s.codeWiseProductionTimeline.length
      ? s.codeWiseProductionTimeline
      : s.codeWiseProduction||[];

  const ordered=[...source].sort((a,b)=>
    numericSequence(a.sequence,999999)-numericSequence(b.sequence,999999)
  );

  for(const item of ordered){
    monthlyTimeline.push({
      shiftDate:s.shiftDate,
      shift:s.shift,
      shiftSequence:numericSequence(item.sequence,monthlyTimeline.length+1),
      designCode:code(item.designCode),
      tileSize:size(item.tileSize),
      startTime:isoOrNull(item.startTime||item.firstProducedAt),
      endTime:isoOrNull(item.endTime||item.lastProducedAt),
      tileCount:Math.round(Math.max(0,Number(item.tileCount||0))),
      production:round(Math.max(0,Number(item.production||0))),
      live:Boolean(s.live)
    });
  }
}

monthlyTimeline.sort((a,b)=>
  a.shiftDate.localeCompare(b.shiftDate) ||
  shiftRank(a.shift)-shiftRank(b.shift) ||
  a.shiftSequence-b.shiftSequence
);

