const days=[...dayMap.values()]
  .sort((a,b)=>a.date.localeCompare(b.date))
  .map(d=>({
    ...d,
    totalProduction:round(d.totalProduction),
    shifts:d.shifts.sort((a,b)=>shiftRank(a.shift)-shiftRank(b.shift))
  }));

const total=round(
  days.reduce((a,d)=>a+d.totalProduction,0)
);

const sizeTotals=[...sizeMap.values()]
  .map(x=>({
    ...x,
    production:round(x.production),
    currentShiftProduction:round(x.currentShiftProduction),
    percentage:total>0
      ? round(x.production/total*100,1)
      : 0
  }))
  .sort((a,b)=>b.production-a.production);

// Map insertion order is already the first-produced date/shift/sequence order.
const codeWiseProduction=[...codeMap.values()]
  .map((x,index)=>{
    const previousShiftsProduction=round(x.production);
    const currentShiftProduction=round(x.currentShiftProduction);
    const totalProduction=round(
      previousShiftsProduction + currentShiftProduction
    );

    return {
      sequence:index+1,
      designCode:x.designCode,
      tileSize:x.tileSize,
      firstShiftDate:x.firstShiftDate,
      firstShift:x.firstShift,
      firstShiftSequence:x.firstShiftSequence,
      firstProducedAt:x.firstProducedAt,
      lastProducedAt:x.lastProducedAt,
      previousShiftsTileCount:Math.round(x.tileCount),
      previousShiftsProduction,
      currentShiftTileCount:Math.round(x.currentShiftTileCount),
      currentShiftProduction,
      totalProduction,
      percentage:total>0
        ? round(totalProduction/total*100,1)
        : 0
    };
  });

msg.headers={
  "Content-Type":"application/json",
  "Cache-Control":"no-store"
};

msg.payload={
  success:true,
  line:r.line,
  month:r.month,
  currentShift:r.include
    ? {
