    return {runtimeTileCount:s.runtimeTileCount,recordedTileCount:s.recordedTileCount,
      countDifference:s.countDifference,unclassifiedTileCount:s.unclassifiedTileCount,
      ignoredRollbacks:Number(e.currentDiagnostics?.ignoredRollbacks||0),
      productionComplete:s.productionComplete};
  })():null,
  totalProduction:total,
