// Convert ordered cumulative shift_count rows into:
// 1) unique design-code totals in first-produced order, and
// 2) a chronological A -> B -> A run timeline.

const rows = (Array.isArray(msg.payload) ? msg.payload : [])
  .filter(row => row?._value!=null && Number.isFinite(Number(row._value)) && Number.isFinite(Date.parse(row._time)))
  .sort((a, b) => {
    const ta = new Date(a?._time || 0).getTime();
    const tb = new Date(b?._time || 0).getTime();
    return ta - tb || Number(a._value)-Number(b._value);
  });

function cleanText(value, fallback) {
  const text = String(value ?? "").trim();
  return text || fallback;
}

function isoTime(value) {
  if (value === undefined || value === null || value === "") return null;
  const ms = new Date(value).getTime();
  return Number.isFinite(ms) ? new Date(ms).toISOString() : null;
}

const totals = new Map();
const timeline = [];

let previousShiftCount = 0;
let activeRun = null;
let ignoredRollbacks = 0;

for (const row of rows) {
  const currentShiftCount = Number(row._value);
  const delta = currentShiftCount - previousShiftCount;

  // Keep the last valid baseline when an older/lower row appears.
  if (!Number.isFinite(delta) || delta < 0) {
    ignoredRollbacks += 1;

    node.warn(
      "Monthly current-shift shift_count rollback ignored: " +
      "previous=" + previousShiftCount +
      ", current=" + currentShiftCount +
      ", time=" + String(row?._time || "")
    );

    continue;
  }

  previousShiftCount = currentShiftCount;

  if (delta === 0) {
    continue;
  }

  const designCode = cleanText(row.designCode, "Unknown");
  const tileSize = cleanText(row.tileSize, "Unknown").toLowerCase().replace(/\s+/g, "").replace(/×/g, "x");
  const producedAt = isoTime(row._time);
  const key = designCode + "|||" + tileSize;

  const total = totals.get(key) || {
    sequence: totals.size + 1,
    designCode,
    tileSize,
    firstProducedAt: producedAt,
    lastProducedAt: producedAt,
    _value: 0
  };

  if (!total.firstProducedAt && producedAt) {
    total.firstProducedAt = producedAt;
  }

  if (producedAt) {
    total.lastProducedAt = producedAt;
  }

  total._value += delta;
  totals.set(key, total);

  // Start a new timeline entry only when the produced design changes.
  if (!activeRun || activeRun.key !== key) {
    activeRun = {
      key,
      sequence: timeline.length + 1,
      designCode,
      tileSize,
      startTime: producedAt,
      endTime: producedAt,
      _value: 0
    };

    timeline.push(activeRun);
  }

  if (!activeRun.startTime && producedAt) {
    activeRun.startTime = producedAt;
  }

  if (producedAt) {
    activeRun.endTime = producedAt;
  }

  activeRun._value += delta;
}

msg.currentDiagnostics={ignoredRollbacks};
msg.topic = "current_codewise";

msg.payload = [...totals.values()]
  .sort((a, b) => a.sequence - b.sequence);

msg.currentTimeline = timeline
  .map(({key, ...item}) => item)
  .sort((a, b) => a.sequence - b.sequence);

node.status({
  fill: ignoredRollbacks > 0 ? "yellow" : "green",
  shape: ignoredRollbacks > 0 ? "ring" : "dot",
  text:
    rows.length + " rows -> " +
    msg.payload.length + " codes, " +
    msg.currentTimeline.length + " runs"
});

return msg;

function norm(v){return String(v||"").toLowerCase().replace(/[^a-z0-9]/g,"");}
function escapeFlux(v){return String(v||"").replace(/\\/g,"\\\\").replace(/"/g,'\\"');}
function escRegex(v){return String(v||"").replace(/[.*+?^${}()|[\]\\]/g,"\\$&");}

function resolveDevice(q){
    const cfg=global.get("counterConfig")||{};
    const requested=String(q.device||"").trim();

    if(requested && cfg[requested]) return requested;

    const line=String(q.line||q.lineName||"").trim();
    if(!line) return "";

    const n=norm(line);

    return Object.keys(cfg).find(id =>
        cfg[id]?.enabled!==false &&
        (
            norm(cfg[id]?.line)===n ||
            norm(cfg[id]?.shortId)===n ||
            norm(id)===n
        )
    ) || "";
}

function addDays(ds,days){
    const [y,m,d]=ds.split("-").map(Number);
    const x=new Date(Date.UTC(y,m-1,d));
    x.setUTCDate(x.getUTCDate()+days);
    return x.toISOString().slice(0,10);
}

function shiftRange(shift,date){
    if(shift==="06-14") return {
        from:`${date}T06:00:00+05:30`,
        to:`${date}T14:00:00+05:30`
    };

    if(shift==="14-22") return {
        from:`${date}T14:00:00+05:30`,
        to:`${date}T22:00:00+05:30`
    };

    if(shift==="22-06") return {
        from:`${date}T22:00:00+05:30`,
        to:`${addDays(date,1)}T06:00:00+05:30`
    };

    return null;
}

function currentShiftInfo(ts=Date.now()){
    const p={};

    for(const part of new Intl.DateTimeFormat("en-CA",{
        timeZone:"Asia/Colombo",
        year:"numeric",
        month:"2-digit",
        day:"2-digit",
        hour:"2-digit",
        hourCycle:"h23"
    }).formatToParts(new Date(ts))){
        if(part.type!=="literal") p[part.type]=part.value;
    }

    const date=`${p.year}-${p.month}-${p.day}`;
    const h=Number(p.hour||0);

    if(h>=6 && h<14) return {
        shift:"06-14",
        date,
        ...shiftRange("06-14",date)
    };

    if(h>=14 && h<22) return {
        shift:"14-22",
        date,
        ...shiftRange("14-22",date)
    };

    if(h>=22) return {
        shift:"22-06",
        date,
        ...shiftRange("22-06",date)
    };

    const prev=addDays(date,-1);

    return {
        shift:"22-06",
        date:prev,
        ...shiftRange("22-06",prev)
    };
}

const q=msg.req?.query||{};
const cfgAll=global.get("counterConfig")||{};
const device=resolveDevice(q);
const date=String(q.date||"").trim();
const shift=String(q.shift||"").trim();
const range=shiftRange(shift,date);

if(
    !device ||
