    !/^\d{4}-\d{2}-\d{2}$/.test(date) ||
    !range
){
    msg.statusCode=400;
    msg.payload={
        success:false,
        error:"line, date and valid shift are required"
    };

    return [null,null,null,msg];
}

const cfg=cfgAll[device];
const line=String(cfg.line||device);
const current=currentShiftInfo();
const isCurrent=
    date===current.date &&
