    {};

const meta={
    requestId:`${msg._msgid||"shift"}-${Date.now()}-${Math.random().toString(16).slice(2)}`,
    device,
    line,
    date,
    shift,
    from:range.from,
    to:range.to,
    isCurrent,
    configuredTileSize:String(ls.tileSize ?? cfg.tileSize ?? ""),
    configuredLineSpeed:Number(ls.lineSpeed ?? cfg.lineSpeed ?? 0),
    plannedDowntime:Number(ls.plannedDowntime ?? cfg.plannedDowntime ?? 0),
    stopDelayMs:Number(ls.stopDelayMs ?? cfg.stopDelayMs ?? 60000)
};

msg.summaryMeta=meta;

// ========================================================
// HISTORICAL / COMPLETED SHIFT
// Read the saved summary, including codeWiseProduction, from MongoDB.
// InfluxDB is intentionally not queried for completed shifts.
// ========================================================
if(!isCurrent){
    msg.collection="shifts";
    msg.operation="find";

    msg.payload=[
        {
            "lineStats.shiftDate":date,
            "lineStats.shift":shift,
            $or:[
                {"lineStats.device":device},
                {
                    "lineStats.lineName":{
                        $regex:`^${escRegex(line)}$`,
                        $options:"i"
                    }
                }
            ]
        },
        {
            sort:{
                "lineStats.updatedAt":-1
            }
        }
    ];

    return [msg,null,null,null];
}

