const influxMsg=RED.util.cloneMessage(msg);
const stopMsg=RED.util.cloneMessage(msg);

const d=escapeFlux(device);
const sh=escapeFlux(shift);
const dt=escapeFlux(date);
const from=escapeFlux(range.from);
const stop=escapeFlux(new Date().toISOString());

influxMsg.query=`
from(bucket:"RCLH")
    |> range(
        start: time(v:"${from}"),
        stop: time(v:"${stop}")
    )
    |> filter(fn:(r)=>
        r._measurement=="tile_events" and
        r.device=="${d}" and
        r.shift=="${sh}" and
        r.shiftDate=="${dt}" and
        r._field=="shift_count"
    )
    |> group(columns:["device","shift","shiftDate"])
    |> sort(columns:["_time"])
    |> keep(columns:[
        "_time",
        "_value",
        "designCode",
        "tileSize"
    ])
`;

stopMsg.collection="stoppages";
stopMsg.operation="find";
stopMsg.payload=[
    {
        device,
        date,
        shift
    },
    {
        sort:{
            stopStart_ts:1
        }
    }
];

return [null,influxMsg,stopMsg,null];

